/**
 * Spawns a physical dynamic object (reacts to collisions, gravity, impulses).
 * Dynamic objects must have their sync ownership managed when clients join/leave.
 */
export function spawnDynamicProp(
  modelHash: bigint,
  position: Vector3,
  dimension = 0,
): MpObject {
  const obj = mp.objects.create({
    model: modelHash,
    position,
    yaw: 0,
    dynamic: true, // Rigid-body physics enabled
    dimension,
  });

  // Tune streaming radius for dynamic physics objects (e.g. 100 meters)
  obj.streamingRadius = 100;
  return obj;
}

/**
 * Reassigns sync ownership of an entity to the closest available player.
 * Ensures smooth physics simulation when the previous host moves away or disconnects.
 */
export function migrateSyncOwnership(entity: MpVehicle | MpObject): boolean {
  if (!entity.exist) {
    return false;
  }

  const [ex, ey, ez] = entity.position;
  let closestPlayer: MpPlayer | null = null;
  let minDistanceSq = Infinity;

  for (const player of mp.players.toArray()) {
    if (player.dimension !== entity.dimension) continue;

    const [px, py, pz] = player.position;
    const distSq = (px - ex) ** 2 + (py - ey) ** 2 + (pz - ez) ** 2;

    if (distSq < minDistanceSq) {
      minDistanceSq = distSq;
      closestPlayer = player;
    }
  }

  if (closestPlayer) {
    entity.owner = closestPlayer; // Assign sync host
    console.log(`[Sync] Assigned entity ${entity.id} sync ownership to ${closestPlayer.nickname}`);
    return true;
  }

  return false;
}

import type { MpPlayer } from '@cybermp/server-types';

export interface BanRecord {
  ip: string;
  nickname: string;
  reason: string;
  bannedAt: number;
  expiresAt: number | null; // null = permanent
}

export const ActiveBans = new Map<string, BanRecord>();

/**
 * Kicks a player immediately with a logged reason.
 */
export function kickPlayer(player: MpPlayer, reason: string = 'Kicked by administrator'): void {
  console.log(`[Admin] Kicking player ${player.nickname} (${player.id}) for: "${reason}"`);
  player.kick(reason);
}

/**
 * Bans a player by IP and immediately disconnects them.
 */
export function banPlayer(
  player: MpPlayer,
  reason: string,
  durationMinutes: number | null = null,
): void {
  const expiresAt = durationMinutes !== null ? Date.now() + durationMinutes * 60 * 1000 : null;

  ActiveBans.set(player.ip, {
    ip: player.ip,
    nickname: player.nickname,
    reason,
    bannedAt: Date.now(),
    expiresAt,
  });

  kickPlayer(player, `Banned: ${reason}`);
}

/**
 * Validates connecting players against the active ban list using their IP.
 * Called in `playerConnected` where the `player.ip` property is available.
 */
export function checkPlayerBan(ip: string): { banned: boolean; reason?: string } {
  const record = ActiveBans.get(ip);
  if (!record) {
    return { banned: false };
  }

  if (record.expiresAt !== null && Date.now() > record.expiresAt) {
    ActiveBans.delete(ip);
    return { banned: false };
  }

  return { banned: true, reason: record.reason };
}

export interface DimensionAllocator {
  allocate(): number;
  free(dimension: number): void;
  isAllocated(dimension: number): boolean;
  activeCount(): number;
}

export function createDimensionAllocator(startDimension: number = 100): DimensionAllocator {
  let nextId = startDimension;
  const freeList: number[] = [];
  const inUse = new Set<number>();

  return {
    allocate(): number {
      let id: number;
      if (freeList.length > 0) {
        id = freeList.pop()!;
      } else {
        id = nextId++;
      }
      inUse.add(id);
      return id;
    },

    free(dimension: number): void {
      if (!inUse.has(dimension)) {
        return;
      }
      inUse.delete(dimension);
      freeList.push(dimension);
    },

    isAllocated(dimension: number): boolean {
      return inUse.has(dimension);
    },

    activeCount(): number {
      return inUse.size;
    },
  };
}

import type { MpPlayer, MpAnyEntity, Vector3, DamageEventData } from '@cybermp/server-types';
import { EntityType } from '@cybermp/server-types';

export interface Safezone {
  id: string;
  name: string;
  vertices: Vector3[];
  height: number;
  dimension: number;
  enabled: boolean;
  occupants: Set<number>; // Entity IDs inside zone
  debugObjects: Set<number>;
}

export interface SafezoneManager {
  zones: Map<string, Safezone>;
  createZone(opts: {
    id: string;
    name: string;
    vertices: Vector3[];
    height: number;
    dimension?: number;
    enabled?: boolean;
    debugVisuals?: boolean;
  }): Safezone;
  removeZone(id: string): void;
  startTick(intervalMs?: number): () => void;
  isPlayerInAnySafezone(player: MpPlayer): boolean;
}

const DEBUG_CORNER_PROP_HASH = 7454566152498118096n; // Radio or marker prop

/**
 * Creates and initializes a procedural Safezone Manager.
 */
export function createSafezoneManager(): SafezoneManager {
  const zones = new Map<string, Safezone>();

  function spawnDebugVisuals(zone: Safezone): void {
    for (const v of zone.vertices) {
      // Bottom corner marker
      const bottomObj = mp.objects.create({
        model: DEBUG_CORNER_PROP_HASH,
        position: v,
        dimension: Math.max(0, zone.dimension),
      });
      zone.debugObjects.add(bottomObj.id);

      // Top corner marker
      const topObj = mp.objects.create({
        model: DEBUG_CORNER_PROP_HASH,
        position: [v[0], v[1], v[2] + zone.height],
        dimension: Math.max(0, zone.dimension),
      });
      zone.debugObjects.add(topObj.id);
    }
  }

  function destroyDebugVisuals(zone: Safezone): void {
    for (const objId of zone.debugObjects) {
      if (mp.objects.exists(objId)) {
        mp.objects.destroy(objId);
      }
    }
    zone.debugObjects.clear();
  }

  function handleEntityEnter(zone: Safezone, entity: MpAnyEntity): void {
    zone.occupants.add(entity.id);

    if (entity.type === EntityType.Player) {
      const player = entity as MpPlayer;
      player.setMeta('isInSafezone', true, true);

      // Notify player via chat or RPC
      player.emit('safezone:enter', zone.name);
      console.log(`[Safezone] Player ${player.nickname} entered "${zone.name}"`);
    }
  }

  function handleEntityLeave(zone: Safezone, entity: MpAnyEntity): void {
    zone.occupants.delete(entity.id);

    if (entity.type === EntityType.Player) {
      const player = entity as MpPlayer;
      player.setMeta('isInSafezone', false, true);

      player.emit('safezone:leave', zone.name);
      console.log(`[Safezone] Player ${player.nickname} exited "${zone.name}"`);
    }
  }

  const manager: SafezoneManager = {
    zones,

    createZone(opts) {
      const zone: Safezone = {
        id: opts.id,
        name: opts.name,
        vertices: opts.vertices,
        height: opts.height,
        dimension: opts.dimension ?? 0,
        enabled: opts.enabled ?? true,
        occupants: new Set(),
        debugObjects: new Set(),
      };

      if (opts.debugVisuals) {
        spawnDebugVisuals(zone);
      }

      zones.set(zone.id, zone);
      return zone;
    },

    removeZone(id: string) {
      const zone = zones.get(id);
      if (!zone) return;

      destroyDebugVisuals(zone);
      zone.occupants.clear();
      zones.delete(id);
    },

    startTick(intervalMs = 100) {
      const intervalId = setInterval(() => {
        if (zones.size === 0) return;

        const players = mp.players.toArray();

        for (const zone of zones.values()) {
          if (!zone.enabled) continue;

          for (const player of players) {
            const isColliding = isInsideSafezone(
              player.position,
              zone.vertices,
              zone.height,
              zone.dimension,
              player.dimension,
            );
            const isContained = zone.occupants.has(player.id);

            if (!isContained && isColliding) {
              handleEntityEnter(zone, player);
            } else if (isContained && !isColliding) {
              handleEntityLeave(zone, player);
            }
          }
        }
      }, intervalMs);

      // Return cleanup function
      return () => {
        clearInterval(intervalId);
        for (const zone of zones.values()) {
          destroyDebugVisuals(zone);
        }
      };
    },

    isPlayerInAnySafezone(player: MpPlayer): boolean {
      for (const zone of zones.values()) {
        if (zone.enabled && zone.occupants.has(player.id)) {
          return true;
        }
      }
      return false;
    },
  };

  return manager;
}

import type { MpVehicle, Vector3, GameHash, CName } from '@cybermp/server-types';
import { VehicleSeat } from '@cybermp/server-types';

export interface SpawnVehicleOptions {
  model: GameHash;
  appearance: CName;
  position: Vector3;
  yaw?: number;
  health?: number;
  dimension?: number;
}

/**
 * Spawns a synchronized server vehicle.
 *
 * @param options Vehicle parameters
 * @returns The instantiated MpVehicle
 */
export function createServerVehicle(options: SpawnVehicleOptions): MpVehicle {
  const vehicle = mp.vehicles.create({
    model: options.model,
    appearance: options.appearance,
    position: options.position,
    yaw: options.yaw ?? 0,
    health: options.health ?? 100,
    dimension: options.dimension ?? 0,
  });

  console.log(`[Vehicles] Created vehicle ID ${vehicle.id} in dimension ${vehicle.dimension}`);
  return vehicle;
}

/**
 * Destroys a server vehicle safely.
 *
 * @param target MpVehicle reference or numeric ID
 */
export function destroyServerVehicle(target: MpVehicle | number): void {
  const id = typeof target === 'number' ? target : target.id;
  if (!mp.vehicles.exists(id)) {
    return;
  }

  mp.vehicles.destroy(target);
  console.log(`[Vehicles] Destroyed vehicle ID ${id}`);
}

/**
 * Inspects all occupants currently seated inside a vehicle.
 */
export function getVehicleOccupants(vehicle: MpVehicle) {
  return {
    driver: vehicle.seats.driver,
    passenger: vehicle.seats.passenger,
    rearLeft: vehicle.seats.rearLeft,
    rearRight: vehicle.seats.rearRight,
    driverBySeat: vehicle.getPlayerInSeat(VehicleSeat.Driver),
  };
}

import type { MpVehicle, MpPlayer } from '@cybermp/server-types';
import { VehicleSeat } from '@cybermp/server-types';

/**
 * Returns all players currently seated in a vehicle.
 */
export function getAllOccupants(vehicle: MpVehicle): MpPlayer[] {
  const occupants: MpPlayer[] = [];
  const seats = [
    vehicle.seats.driver,
    vehicle.seats.passenger,
    vehicle.seats.rearLeft,
    vehicle.seats.rearRight,
  ];

  for (const player of seats) {
    if (player && player.exist) {
      occupants.push(player);
    }
  }
  return occupants;
}

/**
 * Identifies the last driver of a vehicle (e.g., for impounding abandoned vehicles).
 */
export function identifyLastDriver(vehicle: MpVehicle): MpPlayer | null {
  // Check active driver first
  if (vehicle.seats.driver) {
    return vehicle.seats.driver;
  }
  // Fall back to historical last occupant
  const lastDriver = vehicle.lastSeats.driver ?? vehicle.getLastPlayerInSeat(VehicleSeat.Driver);
  return lastDriver && lastDriver.exist ? lastDriver : null;
}

/**
 * Ejects all passengers from a vehicle, keeping the driver.
 */
export function ejectPassengers(vehicle: MpVehicle): void {
  const passengerSeats = [VehicleSeat.Passenger, VehicleSeat.RearLeft, VehicleSeat.RearRight];
  for (const seat of passengerSeats) {
    const occupant = vehicle.getPlayerInSeat(seat);
    if (occupant) {
      occupant.emit('vehicle:eject');
      console.log(`[Vehicles] Ejected passenger ${occupant.nickname} from seat ${seat}`);
    }
  }
}

import * as CyberEnums from '@cybermp/client-types/enums';
import type { vehicleBaseObject } from '@cybermp/client-types/game';

/**
 * The 10 deformation blend shape parts on standard Cyberpunk vehicles.
 */
const DEFORMATION_PARTS = [
  'hood_destruction',
  'wheel_f_l_destruction',
  'wheel_f_r_destruction',
  'bumper_b_destruction',
  'bumper_f_destruction',
  'door_f_l_destruction',
  'door_f_r_destruction',
  'trunk_destruction',
  'bumper_b_destruction_side_2',
  'bumper_f_destruction_side_2',
] as const;

/**
 * Performs a 100% complete physical, visual, and persistent restoration
 * of the given vehicle entity.
 */
export function repairVehicle(vehicle: vehicleBaseObject): void {
  if (!vehicle) {
    return;
  }

  const ps = vehicle.GetVehiclePS();
  const comp = vehicle.GetVehicleComponent();
  const vehType = vehicle.GetVehicleType();

  // Reset bumper states & deformation floats for cars/trucks
  if (vehType !== CyberEnums.gamedataVehicleType.Bike) {
    comp.bumperFrontState = 0;
    comp.bumperBackState = 0;

    for (const part of DEFORMATION_PARTS) {
      mp.game.entAnimationControllerComponent.SetInputFloat(vehicle, part, 0.0);
    }
  }

  // Reset damage level
  comp.damageLevel = 0;

  // Restore flat/broken tires
  const flatTireIndex = (vehicle as any).GetFlatTireIndex?.() ?? -1;
  if (flatTireIndex >= 0) {
    for (let i = 0; i < 4; i++) {
      (vehicle as any).ToggleBrokenTire?.(i, false);
    }
  }

  // Reset physical deformation grid and window glass
  vehicle.DestructionResetGrid();
  vehicle.DestructionResetGlass();

  // Update visual and engine damage effects
  comp.UpdateDamageEngineEffects();
  comp.RepairVehicle();
  comp.VehicleVisualDestructionSetup();

  // Close persistent doors and windows
  if (ps) {
    ps.CloseAllVehDoors(true);
    ps.CloseAllVehWindows();
    ps.ForcePersistentStateChanged();
  }
}

/**
 * Repairs the vehicle currently occupied by the local player.
 */
export function repairCurrentVehicle(): boolean {
  const playerObj = mp.game.GetPlayerObject();
  if (!playerObj) {
    return false;
  }

  const vehicle = mp.game.GetMountedVehicle(playerObj);
  if (!vehicle) {
    return false;
  }

  repairVehicle(vehicle);
  return true;
}

import type { vehicleTPPCameraComponent } from '@cybermp/client-types/game';

let activeTppCam: vehicleTPPCameraComponent | null = null;
let baseFov = 75;
let currentFov = 75;
const BOOST_FOV_INCREASE = 15;
const LERP_RATE = 0.1;

/**
 * Finds the active third-person vehicle camera component on the player.
 */
export function getVehicleTppCamera(): vehicleTPPCameraComponent | null {
  const components = mp.game.GetPlayer().GetComponents();
  for (const comp of components) {
    if (comp.IsA('vehicleTPPCameraComponent')) {
      return comp as vehicleTPPCameraComponent;
    }
  }
  return null;
}

/**
 * Smoothly interpolates vehicle camera FOV using REDengine native LerpF.
 *
 * @param boosting True while nitro key is pressed; false when released.
 */
export function updateNitroCameraFov(boosting: boolean): void {
  if (!activeTppCam) {
    activeTppCam = getVehicleTppCamera();
    if (activeTppCam) {
      baseFov = activeTppCam.GetFOV();
      currentFov = baseFov;
    }
  }
  if (!activeTppCam) return;

  const targetFov = boosting ? baseFov + BOOST_FOV_INCREASE : baseFov;
  currentFov = Number(mp.game.LerpF(LERP_RATE, currentFov, targetFov).toFixed(4));
  activeTppCam.SetFOV(currentFov);
}

import type { vehicleBaseObject } from '@cybermp/client-types/game';

interface NitroImpulseOptions {
  force?: number;
  checkIsOnGround?: boolean;
  maxSpeedKmh?: number;
}

/**
 * Applies a directional nitro forward impulse to a vehicle.
 * Verifies that the local player is the driver and checks ground/speed constraints.
 */
export function applyNitroImpulse(
  vehicle: vehicleBaseObject,
  options: NitroImpulseOptions = {},
): boolean {
  if (!vehicle) {
    return false;
  }

  const { force = 10.0, checkIsOnGround = true, maxSpeedKmh = 250.0 } = options;

  // Verify that the local player is the driver (do not boost if passenger)
  if (!vehicle.IsPlayerDriver()) {
    return false;
  }

  // Prevent boosting mid-air if ground check is requested
  if (checkIsOnGround && !vehicle.IsOnGround()) {
    return false;
  }

  // Prevent exceeding max speed cap
  const currentSpeed = getVehicleSpeedKmh(vehicle);
  if (currentSpeed > maxSpeedKmh) {
    return false;
  }

  // Extract forward direction from vehicle orientation
  const orientation = vehicle.GetWorldTransform().Orientation;
  const forward = getForwardFromQuaternion(orientation);

  const linearVelocity = Object.assign(new mp.game.Vector3(), {
    x: forward.x * force,
    y: forward.y * force,
    z: forward.z * force,
  });

  const angularVelocity = Object.assign(new mp.game.Vector3(), {
    x: 0,
    y: 0,
    z: 0,
  });

  // Apply physical velocity impulse
  return vehicle.AddLinelyVelocity(linearVelocity, angularVelocity);
}

/**
 * Instantly stops a vehicle by resetting linear and angular velocity.
 */
export function stopVehicle(vehicle: vehicleBaseObject): void {
  if (!vehicle) {
    return;
  }

  const zero = Object.assign(new mp.game.Vector3(), { x: 0, y: 0, z: 0 });
  vehicle.ChangeLinelyVelocity(zero, zero, 0);
}

import type { vehicleBaseObject } from '@cybermp/client-types/game';

interface SitInVehicleOptions {
  slotName?: string;
  instant?: boolean;
}

/**
 * Mounts the local player into a networked vehicle by its network ID.
 * If the vehicle entity is not yet streamed in, listens to `vehicleStreamIn`
 * until the entity becomes available.
 */
export function sitInVehicle(
  vehicleNetId: number,
  options: SitInVehicleOptions = {},
): void {
  const { slotName = 'seat_front_left', instant = true } = options;

  const onVehicleStreamIn = (netId: number, hash: number): void => {
    if (netId !== vehicleNetId) {
      return;
    }

    // Leave current vehicle if already seated
    leaveVehicle(true);

    const entityID = Object.assign(new mp.game.entEntityID(), {
      hash,
    });

    const targetVehicle = mp.game.ScriptGameInstance.FindEntityByID(entityID);
    if (!targetVehicle) {
      return;
    }

    const player = mp.game.GetPlayer();
    if (!player) {
      return;
    }

    // 1. Mount Event Data
    const data = Object.assign(new mp.game.gameMountEventData(), {
      isInstant: instant,
      slotName,
      mountParentEntityId: targetVehicle.GetEntityID(),
      entryAnimName: 'forcedTransition',
    });

    // 2. Mounting Slot ID
    const slotID = Object.assign(new mp.game.gamemountingMountingSlotId(), {
      id: slotName,
    });

    // 3. Low-Level Mounting Info
    const mountingInfo = Object.assign(new mp.game.gamemountingMountingInfo(), {
      childId: player.GetEntityID(),
      parentId: targetVehicle.GetEntityID(),
      slotId: slotID,
    });

    // 4. Mounting Request
    const mountEvent = Object.assign(new mp.game.gamemountingMountingRequest(), {
      lowLevelMountingInfo: mountingInfo,
      mountData: data,
    });

    // Dispatch mounting to REDengine facility
    mp.game.ScriptGameInstance.GetMountingFacility().Mount(mountEvent);

    // Clean up stream listener once mounted
    mp.events.off('vehicleStreamIn', onVehicleStreamIn);
  };

  // Check if vehicle is already streamed in
  const streamedPool = mp.network.getStreamedPool('CVehicle');
  const alreadyStreamedHash = streamedPool.find(
    (hash) => mp.network.getVehicleId(hash) === vehicleNetId,
  );

  if (alreadyStreamedHash !== undefined) {
    onVehicleStreamIn(vehicleNetId, alreadyStreamedHash);
    return;
  }

  // Otherwise, wait for stream in
  mp.events.on('vehicleStreamIn', onVehicleStreamIn);
}

/**
 * Unmounts the local player from their current vehicle.
 */
export function leaveVehicle(instant: boolean = true): void {
  const playerObj = mp.game.GetPlayerObject();
  if (!playerObj) {
    return;
  }

  const vehicle = mp.game.GetMountedVehicle(playerObj);
  if (!vehicle) {
    return;
  }

  const slot = vehicle.GetSlotIdForMountedObject(playerObj);

  const data = Object.assign(new mp.game.gameMountEventData(), {
    isInstant: instant,
    slotName: slot,
    mountParentEntityId: vehicle.GetEntityID(),
    entryAnimName: 'forcedTransition',
  });

  const slotID = Object.assign(new mp.game.gamemountingMountingSlotId(), {
    id: slot,
  });

  const mountingInfo = Object.assign(new mp.game.gamemountingMountingInfo(), {
    childId: mp.game.GetPlayer().GetEntityID(),
    parentId: vehicle.GetEntityID(),
    slotId: slotID,
  });

  const unmountEvent = Object.assign(new mp.game.gamemountingUnmountingRequest(), {
    lowLevelMountingInfo: mountingInfo,
    mountData: data,
  });

  mp.game.ScriptGameInstance.GetMountingFacility().Unmount(unmountEvent);
}

import type { Quaternion, Vector3 } from '@cybermp/client-types/game';

/**
 * Extracts a normalized 3D forward vector from a REDengine orientation Quaternion.
 */
export function getForwardFromQuaternion(q: Quaternion): { x: number; y: number; z: number } {
  const x = q.i;
  const y = q.j;
  const z = q.k;
  const w = q.r;

  return {
    x: 2 * (x * y - w * z),
    y: 1 - 2 * (x * x + z * z),
    z: 2 * (y * z + w * x),
  };
}

import type { vehicleBaseObject } from '@cybermp/client-types/game';

/**
 * Calculates the true speed of a vehicle in kilometers per hour (km/h)
 * using the official REDengine 'vehicle_ui' 'speed_to_multiplier' curve.
 */
export function getVehicleSpeedKmh(vehicle: vehicleBaseObject): number {
  if (!vehicle) {
    return 0;
  }

  const rawSpeed = vehicle.GetCurrentSpeed();
  const statsDataSystem = mp.game.ScriptGameInstance.GetStatsDataSystem();

  const multiplier = statsDataSystem.GetValueFromCurve(
    'vehicle_ui',
    rawSpeed,
    'speed_to_multiplier',
  );

  return rawSpeed * multiplier * 1.61;
}

/**
 * Calculates the true speed of a vehicle in miles per hour (mph).
 */
export function getVehicleSpeedMph(vehicle: vehicleBaseObject): number {
  return getVehicleSpeedKmh(vehicle) / 1.60934;
}

// In client tick or update interval:
let speedUpdateTimer: ReturnType<typeof setInterval> | null = null;

export function startSpeedometerSync(): void {
  if (speedUpdateTimer) return;

  speedUpdateTimer = setInterval(() => {
    const playerObj = mp.game.GetPlayerObject();
    if (!playerObj) return;

    const vehicle = mp.game.GetMountedVehicle(playerObj);
    if (!vehicle || !vehicle.IsPlayerDriver()) {
      return;
    }

    const kmh = Math.round(getVehicleSpeedKmh(vehicle));
    mp.events.emitCef('speedometer:update', {
      kmh,
      rpm: vehicle.GetRpmValue?.() ?? 0,
      gear: vehicle.GetCurrentGear?.() ?? 1,
    });
  }, 50); // 20 updates per second
}

export function stopSpeedometerSync(): void {
  if (speedUpdateTimer) {
    clearInterval(speedUpdateTimer);
    speedUpdateTimer = null;
  }
}

import type { vehicleBaseObject, vehicleControllerPS } from '@cybermp/client-types/game';
import { vehicleELightMode } from '@cybermp/client-types/enums';

/**
 * Toggles the vehicle engine state on or off.
 *
 * @param vehicle Target vehicle
 * @param engineOn Target ignition state
 */
export function setVehicleEngine(vehicle: vehicleBaseObject, engineOn: boolean): void {
  if (!vehicle) return;

  // TurnEngineOn controls physical engine ignition and idle audio
  vehicle.TurnEngineOn(engineOn);

  // TurnVehicleOn controls auxiliary electronics and dashboard HUDs
  vehicle.TurnVehicleOn(engineOn);

  console.log(`[Vehicle] Engine state set to: ${engineOn}`);
}

/**
 * Configures vehicle headlight intensity and mode.
 */
export function setVehicleHeadlights(
  vehicle: vehicleBaseObject,
  mode: vehicleELightMode,
): void {
  const controller: vehicleControllerPS = vehicle.GetVehicleControllerPS();
  if (!controller) return;

  controller.SetHeadLightMode(mode);
}

/**
 * Cycles headlights through Off -> LowBeams -> HighBeams.
 */
export function cycleHeadlights(vehicle: vehicleBaseObject): void {
  const controller: vehicleControllerPS = vehicle.GetVehicleControllerPS();
  if (!controller) return;

  controller.CycleHeadLightMode(true);
}

import type { vehicleBaseObject } from '@cybermp/client-types/game';

/**
 * Detaches a named body component from the vehicle chassis.
 *
 * @param vehicle Target vehicle
 * @param partName Name of the part mesh (e.g. 'hood', 'trunk', 'bumper_front', 'door_front_left')
 */
export function detachVehiclePart(vehicle: vehicleBaseObject, partName: string): void {
  if (!vehicle) return;

  vehicle.DetachPart(partName);
  console.log(`[Vehicle] Detached part: ${partName}`);
}

/**
 * Strips all external body panels from a vehicle (demolition derby mode).
 */
export function stripVehiclePanels(vehicle: vehicleBaseObject): void {
  const parts = [
    'hood',
    'trunk',
    'bumper_front',
    'bumper_back',
    'door_front_left',
    'door_front_right',
    'door_back_left',
    'door_back_right',
  ];

  for (const part of parts) {
    detachVehiclePart(vehicle, part);
  }
}

import type { vehicleBaseObject, vehicleControllerPS } from '@cybermp/client-types/game';
import {
  vehicleEVehicleDoor,
  vehicleVehicleDoorState,
  vehicleEVehicleWindowState,
} from '@cybermp/client-types/enums';

/**
 * Sets the physical state of a vehicle door, hood, or trunk.
 *
 * @param vehicle Target vehicle instance
 * @param door Target aperture (e.g. hood, trunk, seat_front_left)
 * @param open Whether to open (true) or close (false)
 * @param immediate If true, skips opening animation
 */
export function setVehicleApertureState(
  vehicle: vehicleBaseObject,
  door: vehicleEVehicleDoor,
  open: boolean,
  immediate: boolean = false,
): void {
  const controller: vehicleControllerPS = vehicle.GetVehicleControllerPS();
  if (!controller) return;

  const targetState = open
    ? vehicleVehicleDoorState.Open
    : vehicleVehicleDoorState.Closed;

  controller.SetDoorState(door, targetState, immediate);
}

/**
 * Toggles the vehicle hood open or closed (useful for car meetups and engine repairs).
 */
export function toggleVehicleHood(vehicle: vehicleBaseObject, open: boolean): void {
  setVehicleApertureState(vehicle, vehicleEVehicleDoor.hood, open);
}

/**
 * Toggles the vehicle trunk open or closed (useful for storing items or contraband).
 */
export function toggleVehicleTrunk(vehicle: vehicleBaseObject, open: boolean): void {
  setVehicleApertureState(vehicle, vehicleEVehicleDoor.trunk, open);
}

/**
 * Sets the power window state (up/closed or down/opened).
 */
export function setVehicleWindowState(
  vehicle: vehicleBaseObject,
  door: vehicleEVehicleDoor,
  lowered: boolean,
): void {
  const controller: vehicleControllerPS = vehicle.GetVehicleControllerPS();
  if (!controller) return;

  const windowState = lowered
    ? vehicleEVehicleWindowState.Open
    : vehicleEVehicleWindowState.Closed;

  controller.SetWindowState(door, windowState);
}

import { vehicleEVehicleDoor } from '@cybermp/client-types/enums';

/**
 * Prepares a vehicle for drive-by combat by rolling down front windows
 * and enforcing the combat lock restriction to prevent accidental ejection.
 */
export function prepareVehicleForCombat(vehicle: vehicleBaseObject): void {
  // 1. Lower driver and passenger side windows for unobstructed aiming
  setVehicleWindowState(vehicle, vehicleEVehicleDoor.seat_front_left, true);
  setVehicleWindowState(vehicle, vehicleEVehicleDoor.seat_front_right, true);

  // 2. Apply gameplay restriction to prevent accidental vehicle ejection during combat maneuvers
  const player = mp.game.GetPlayer();
  if (player) {
    const effectSystem = mp.game.ScriptGameInstance.GetStatusEffectSystem();
    effectSystem.ApplyStatusEffect(
      player.GetEntityID(),
      'GameplayRestriction.VehicleCombatBlockExit',
      player.GetRecordID(),
      player.GetEntityID(),
    );
  }

  console.log('[Combat] Vehicle prepared for drive-by combat');
}

/**
 * Restores normal driving conditions after combat ends.
 */
export function endVehicleCombat(vehicle: vehicleBaseObject): void {
  // Raise windows
  setVehicleWindowState(vehicle, vehicleEVehicleDoor.seat_front_left, false);
  setVehicleWindowState(vehicle, vehicleEVehicleDoor.seat_front_right, false);

  // Remove exit lock
  const player = mp.game.GetPlayerObject();
  if (player && mp.game.StatusEffectHelper) {
    mp.game.StatusEffectHelper.RemoveStatusEffect(
      player,
      'GameplayRestriction.VehicleCombatBlockExit',
      undefined,
    );
  }
}

import type { vehicleBaseObject } from '@cybermp/client-types/game';

/**
 * Unlocks the native vehicle visual customization system on client start.
 */
export function unlockVisualCustomization(): void {
  const questsSystem = mp.game.ScriptGameInstance.GetQuestsSystem();
  if (questsSystem) {
    questsSystem.SetFactStr('vvc_visual_customization_unlocked', 1);
  }
}

/**
 * Triggers the CrystalCoat holographic shader pulse across the vehicle body panels.
 *
 * @param vehicle Target vehicle
 * @param play Whether to trigger the color wave animation
 * @param instant If true, changes color without wave transition
 * @param affectRims Whether wheel rims also change coloration
 */
export function playCrystalCoatShader(
  vehicle: vehicleBaseObject,
  play: boolean = true,
  instant: boolean = false,
  affectRims: boolean = true,
): void {
  if (!vehicle) return;

  vehicle.PlayVehicleVisualCustomizationShader(play, instant, affectRims);
  console.log('[Vehicle] CrystalCoat customization shader invoked');
}
